insert into public.projects (title, description, category, tags, image_url, demo_url, code_url, links, featured, sort_order)
select * from (values
  ('Kodi · Rental Management Platform', 'Rent collection, utility billing and caretaker tools for Kenyan landlords. Four apps on one PostgreSQL core (owner web app, REST API, Flutter caretaker app and a Gemini AI sales agent) with M-Pesa payments, SMS reminders and CI on GitHub Actions. Live on Render.', 'Fintech', array['React', 'Node.js', 'PostgreSQL', 'Flutter', 'M-Pesa', 'Gemini']::text[], '/projects/kodi.png', 'https://rental-managemtn-system-frontend.onrender.com', 'https://github.com/sejoh2/Rental_managemtn_system_backend', '[{"label":"API docs","url":"https://rental-managemtn-system-backend.onrender.com/api-docs"},{"label":"AI agent","url":"https://rental-management-system-agent.onrender.com"},{"label":"Web app code","url":"https://github.com/sejoh2/Rental_managemtn_system_frontend"},{"label":"Mobile app code","url":"https://github.com/sejoh2/Rental_Management_System_Mobile"}]'::jsonb, true, 1),
  ('Kodi AI Agent', 'An AI sales and support agent for Kodi. It qualifies landlord leads over web chat, WhatsApp and Messenger, books demos in Google Calendar, and gives owners a morning brief and a voice assistant. Actions run at three autonomy levels (act alone, needs approval with a PIN for money, alert at once) with an append-only audit log.', 'AI Agents', array['Node.js', 'Express', 'PostgreSQL', 'Gemini', 'WhatsApp Cloud API', 'Google Calendar', 'React']::text[], '/projects/kodi-agent.jpg', 'https://rental-management-system-agent.onrender.com', null, '[{"label":"Kodi web app","url":"https://rental-managemtn-system-frontend.onrender.com"}]'::jsonb, true, 2),
  ('tuRide · Ride Aggregator', 'Compares ride-hailing fares across Uber, Bolt, Yego and Faras in real time. Riders enter pickup and drop-off and get a side-by-side comparison of price, arrival time and vehicle type in under 5 seconds, so they stop overpaying. Built at AnnexTechnologies.', 'Mobility', array['Node.js', 'PostgreSQL', 'REST APIs']::text[], '/projects/turide.jpg', 'https://tu-ride.netlify.app', null, '[{"label":"Case study","url":"https://annex-technologies.com/projects/turide-ride-aggregator-platform-8a9d9e"}]'::jsonb, true, 3),
  ('WayPoint CRM (Wakandi)', 'The in-house CRM replacing HubSpot: shared inbox for email, calls and SMS, ticket and deal pipelines, quotes with PDF generation, and meeting scheduling on Microsoft calendars.', 'Work · Private', array['Next.js', 'TypeScript', 'PostgreSQL', 'Microsoft Graph']::text[], null, null, null, null, true, 4),
  ('Forex Trading Agent', 'A multi-agent research system: seven analyst agents vote on trades, a code-only risk manager sizes positions, and every strategy is tested walk-forward. 432 automated tests.', 'AI · Research', array['Python', 'pandas', 'scikit-learn', 'MetaTrader 5']::text[], null, null, 'https://github.com/sejoh2/forex-trading-agent', null, true, 5),
  ('SACCO Lead-Qualification Agent', 'An MCP agent that researches SACCOs from public sources, cleans and scores them out of 100 on seven factors, and saves nothing without human approval.', 'AI Agents', array['MCP', 'Node.js', 'PostgreSQL']::text[], null, null, null, null, true, 6),
  ('Kweli Rentals Mobile App', 'A Flutter marketplace that brings together home finders, landlords and movers, with map search, photo and video listings, and real-time updates.', 'Mobile', array['Flutter', 'Node.js', 'Socket.IO', 'Firebase']::text[], 'https://i.postimg.cc/5y6RWjrC/image.png', null, null, null, false, 7),
  ('PM Furniture E-commerce', 'An SEO-friendly storefront showcasing a furniture maker''s products, managed through Sanity CMS.', 'Web', array['React', 'Firebase', 'Sanity CMS']::text[], 'https://i.postimg.cc/3xnfNXHg/image.png', 'https://effervescent-flan-877211.netlify.app/', 'https://github.com/joseh33/pm-furniture-website', null, false, 8)
) as v(title, description, category, tags, image_url, demo_url, code_url, links, featured, sort_order)
where not exists (select 1 from public.projects);

